/**
 * PetWash™ Unified Payment Tables — Spec Section 8
 *
 * pw_payments   — one row per customer-facing money movement (all 4 flows)
 * pw_provider_payouts — one row per provider settlement
 *
 * DESIGN RULES:
 *  - These tables do NOT replace existing tables (nayax_transactions,
 *    credit_transactions, general_ledger). They are the unified financial
 *    record that links all flows for reconciliation + ITA reporting.
 *  - All monetary columns are stored as INTEGER CENTS (ILS × 100).
 *    Divide by 100 for display. Never store float for money.
 *  - transaction_type values must match TRANSACTION_TYPES in finance-flow-types.ts
 *  - commercial_model: 'MARKETPLACE_COMMISSION' | 'PRINCIPAL'
 *      MARKETPLACE_COMMISSION = platform keeps commission, passes rest to provider
 *      PRINCIPAL = platform is the seller, provider is a sub-contractor
 */

import {
  pgTable,
  serial,
  varchar,
  integer,
  boolean,
  timestamp,
  jsonb,
  text,
  index,
  uniqueIndex,
} from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";

// ── Unified Payments Table ─────────────────────────────────────────────────────

export const pwPayments = pgTable("pw_payments", {
  id: serial("id").primaryKey(),

  // ── Identity & idempotency ──────────────────────────────────────────────────
  paymentId: varchar("payment_id").unique().notNull(),          // PW-PAY-{year}-{nanoid8}
  idempotencyKey: varchar("idempotency_key").unique(),          // caller-supplied key

  // ── Flow classification ─────────────────────────────────────────────────────
  /** One of the TRANSACTION_TYPES values from shared/finance-flow-types.ts */
  transactionType: varchar("transaction_type").notNull(),
  /** k9000 | sitter-suite | walk-my-pet | pettrek | pet-wash-hub | paw-finder | plush-lab | wallet | egift */
  vertical: varchar("vertical").notNull(),
  /** MARKETPLACE_COMMISSION | PRINCIPAL */
  commercialModel: varchar("commercial_model").notNull(),

  // ── Parties ─────────────────────────────────────────────────────────────────
  customerId: varchar("customer_id"),                           // Firebase UID — null for anonymous K9000
  providerId: varchar("provider_id"),                          // null for direct-sale flows
  machineId: varchar("machine_id"),                            // K9000 only

  // ── Amounts (all INTEGER CENTS, ILS × 100) ──────────────────────────────────
  grossCents: integer("gross_cents").notNull(),                 // Amount collected from customer (incl. VAT)
  vatCents: integer("vat_cents").notNull(),                     // VAT owed by PetWash on this transaction
  platformFeeCents: integer("platform_fee_cents").notNull().default(0),   // Commission or full gross (direct)
  processorFeeCents: integer("processor_fee_cents").notNull().default(0), // Nayax fee
  providerGrossCents: integer("provider_gross_cents").notNull().default(0), // Provider pre-VAT share
  providerPayoutCents: integer("provider_payout_cents").notNull().default(0), // Provider net after their VAT
  netRevenueCents: integer("net_revenue_cents").notNull(),       // PetWash net revenue

  // ── VAT metadata ────────────────────────────────────────────────────────────
  vatRate: varchar("vat_rate").notNull().default("0.18"),       // String to avoid float precision loss
  /** deferred_liability | taxable_sale — for wallet/egift only */
  vatMode: varchar("vat_mode"),
  requiresProviderTaxInvoice: boolean("requires_provider_tax_invoice").notNull().default(false),

  // ── Payment instrument (Section 10 spec) ────────────────────────────────────
  /** credit_card | debit_card | wallet | egift | cash | nayax_nfc */
  paymentMethod: varchar("payment_method"),
  /** nayax | stripe | manual — defaults nayax per spec Section 9 */
  paymentProcessor: varchar("payment_processor").default("nayax"),
  /** true when any portion was covered by wallet/egift balance */
  walletUsed: boolean("wallet_used").notNull().default(false),

  // ── Invoice & receipt references (Section 10 spec) ───────────────────────────
  /** חשבונית מס / tax invoice ID — issued when vat_required = true */
  invoiceId: varchar("invoice_id"),
  /** receipt ID — issued for WALLET_TOPUP and GIFT_PURCHASE (no VAT) */
  receiptId: varchar("receipt_id"),                            // digital_receipts.receipt_number
  /** Platform commission invoice issued TO provider (Section 8 Model B) */
  commissionInvoiceId: varchar("commission_invoice_id"),

  // ── Other references ─────────────────────────────────────────────────────────
  bookingId: varchar("booking_id"),
  nayaxTransactionId: varchar("nayax_transaction_id"),
  walletLedgerEntryId: varchar("wallet_ledger_entry_id"),
  generalLedgerEntryId: varchar("general_ledger_entry_id"),

  // ── State machine ────────────────────────────────────────────────────────────
  /**
   * CREATED → AUTHORISED → CAPTURED → SETTLED
   *                                 ↘ REFUNDED | REVERSED | CANCELLED
   * CAPTURED → CREDITED_TO_WALLET (wallet top-up flow)
   * SETTLED  → CONSUMED (wallet redemption flow)
   */
  status: varchar("status").notNull().default("created"),

  // ── Audit ────────────────────────────────────────────────────────────────────
  metadata: jsonb("metadata"),                                  // arbitrary context (nayax raw, webhook body, etc.)
  createdAt: timestamp("created_at").defaultNow().notNull(),
  settledAt: timestamp("settled_at"),
  reversedAt: timestamp("reversed_at"),
}, (t) => ({
  paymentIdIdx:       uniqueIndex("idx_pw_pay_payment_id").on(t.paymentId),
  idempotencyIdx:     uniqueIndex("idx_pw_pay_idempotency").on(t.idempotencyKey),
  customerIdx:        index("idx_pw_pay_customer").on(t.customerId),
  providerIdx:        index("idx_pw_pay_provider").on(t.providerId),
  verticalIdx:        index("idx_pw_pay_vertical").on(t.vertical),
  txTypeIdx:          index("idx_pw_pay_tx_type").on(t.transactionType),
  statusIdx:          index("idx_pw_pay_status").on(t.status),
  bookingIdx:         index("idx_pw_pay_booking").on(t.bookingId),
  nayaxIdx:           index("idx_pw_pay_nayax").on(t.nayaxTransactionId),
  createdAtIdx:       index("idx_pw_pay_created_at").on(t.createdAt),
}));

export const insertPwPaymentSchema = createInsertSchema(pwPayments).omit({
  id: true,
  createdAt: true,
});
export type InsertPwPayment = z.infer<typeof insertPwPaymentSchema>;
export type PwPayment = typeof pwPayments.$inferSelect;

// ── Provider Payouts Table ────────────────────────────────────────────────────

export const pwProviderPayouts = pgTable("pw_provider_payouts", {
  id: serial("id").primaryKey(),

  payoutId: varchar("payout_id").unique().notNull(),            // PW-POUT-{year}-{nanoid8}
  paymentId: varchar("payment_id").notNull(),                   // FK → pw_payments.payment_id

  // ── Parties ─────────────────────────────────────────────────────────────────
  providerId: varchar("provider_id").notNull(),
  vertical: varchar("vertical").notNull(),
  commercialModel: varchar("commercial_model").notNull(),       // MARKETPLACE_COMMISSION | PRINCIPAL

  // ── Amounts (CENTS) ──────────────────────────────────────────────────────────
  grossCents: integer("gross_cents").notNull(),                 // Provider's share before their VAT
  vatInShareCents: integer("vat_in_share_cents").notNull(),     // VAT embedded in provider's share
  netCents: integer("net_cents").notNull(),                     // Provider receives this (gross - vatInShare)
  commissionCents: integer("commission_cents").notNull(),       // Platform commission deducted
  commissionRate: varchar("commission_rate").notNull(),         // e.g. "0.15"

  // ── Invoice tracking — Section 8 Model B dual-invoice requirement ────────────
  /**
   * Invoice 1: Provider → Pet Wash (provider's service invoice)
   * Required when provider is NOT עוסק פטור.
   */
  requiresTaxInvoice: boolean("requires_tax_invoice").notNull().default(true),
  providerIsExempt: boolean("provider_is_exempt").notNull().default(false),
  providerTaxInvoiceId: varchar("provider_tax_invoice_id"),

  /**
   * Invoice 2: Pet Wash → Provider (platform commission invoice)
   * Pet Wash charges the provider for the commission service.
   * Required for all MARKETPLACE_COMMISSION bookings.
   */
  commissionInvoiceId: varchar("commission_invoice_id"),
  commissionInvoiceIssuedAt: timestamp("commission_invoice_issued_at"),

  // ── State ───────────────────────────────────────────────────────────────────
  /** pending | held_in_escrow | ready_for_payout | paid | cancelled | reversed */
  status: varchar("status").notNull().default("pending"),

  // ── Timing ──────────────────────────────────────────────────────────────────
  escrowReleaseAt: timestamp("escrow_release_at"),              // 72h post-service by default
  paidAt: timestamp("paid_at"),
  createdAt: timestamp("created_at").defaultNow().notNull(),

  metadata: jsonb("metadata"),
}, (t) => ({
  payoutIdIdx:   uniqueIndex("idx_pw_pout_payout_id").on(t.payoutId),
  paymentIdIdx:  index("idx_pw_pout_payment_id").on(t.paymentId),
  providerIdx:   index("idx_pw_pout_provider").on(t.providerId),
  statusIdx:     index("idx_pw_pout_status").on(t.status),
  releaseIdx:    index("idx_pw_pout_release").on(t.escrowReleaseAt),
}));

export const insertPwProviderPayoutSchema = createInsertSchema(pwProviderPayouts).omit({
  id: true,
  createdAt: true,
});
export type InsertPwProviderPayout = z.infer<typeof insertPwProviderPayoutSchema>;
export type PwProviderPayout = typeof pwProviderPayouts.$inferSelect;

// ─────────────────────────────────────────────────────────────────────────────
// pw_tax_documents — First-class accounting documents (Spec Section 8)
//
// Every customer-facing or accounting document MUST have a row here.
// Do NOT store documents only inside pw_payments.metadata JSON.
//
// document_type values:
//   RECEIPT              — anonymous / one-time sale receipt (K9000 walk-in)
//   TOPUP_RECEIPT        — stored-value top-up confirmation (no VAT event yet)
//   TAX_INVOICE          — חשבונית מס (VAT invoice) for taxable service consumption
//   CREDIT_NOTE          — זיכוי — issued on refund / reversal
//   COMMISSION_INVOICE   — platform commission invoice to provider (marketplace)
//   CHARGEBACK_NOTICE    — chargeback record + dispute audit trail
//   ADJUSTMENT_NOTE      — manual adjustment memo with admin auth
// ─────────────────────────────────────────────────────────────────────────────

export const pwTaxDocuments = pgTable("pw_tax_documents", {
  id: serial("id").primaryKey(),

  // ── Identity ────────────────────────────────────────────────────────────────
  taxDocId:     varchar("tax_doc_id").unique().notNull(),   // TAX-{year}-{nanoid8}
  documentType: varchar("document_type").notNull(),         // see enum above

  // ── Links ───────────────────────────────────────────────────────────────────
  relatedPaymentId: varchar("related_payment_id"),          // FK → pw_payments.payment_id
  relatedPayoutId:  varchar("related_payout_id"),           // FK → pw_provider_payouts.payout_id
  bookingId:        varchar("booking_id"),

  // ── Parties ─────────────────────────────────────────────────────────────────
  customerId:  varchar("customer_id"),
  providerId:  varchar("provider_id"),
  machineId:   varchar("machine_id"),

  // ── Amounts (CENTS, ILS × 100) ───────────────────────────────────────────────
  grossCents:   integer("gross_cents").notNull().default(0),
  vatCents:     integer("vat_cents").notNull().default(0),
  netCents:     integer("net_cents").notNull().default(0),
  currency:     varchar("currency").notNull().default("ILS"),

  // ── VAT metadata ────────────────────────────────────────────────────────────
  vatRate:     varchar("vat_rate").default("0.18"),
  vatNumber:   varchar("vat_number").default("516788400"), // Pet Wash company VAT — confirm with accountant

  // ── External accounting reference ───────────────────────────────────────────
  externalDocId:  varchar("external_doc_id"),              // e.g. DocuSeal / accounting system ID
  sequenceYear:   integer("sequence_year"),                 // ITA: calendar year of issuance
  sequenceNumber: integer("sequence_number"),               // ITA: monotonic per type per year

  // ── Document content ────────────────────────────────────────────────────────
  payload: jsonb("payload").notNull().default({}),          // full document snapshot

  // ── State ───────────────────────────────────────────────────────────────────
  status:   varchar("status").notNull().default("issued"),  // issued | voided | amended
  issuedAt: timestamp("issued_at").defaultNow().notNull(),
  voidedAt: timestamp("voided_at"),

  // ── Google Drive archival (Section 2.2 + 5 of Google Architecture Policy) ──
  driveFileId:     text("drive_file_id"),                   // Google Drive file ID of PDF copy
  driveFolderId:   text("drive_folder_id"),                 // Parent folder ID in Drive
  pdfSha256:       text("pdf_sha256"),                      // SHA-256 of uploaded PDF (integrity)
  archiveStatus:   text("archive_status").notNull().default("PENDING"), // PENDING|PROCESSING|ARCHIVED|FAILED
  archiveAttempts: integer("archive_attempts").notNull().default(0),   // Upload attempt count
  archivedAt:      timestamp("archived_at"),                // When successfully archived to Drive
  retentionUntil:  timestamp("retention_until"),            // ITA 7-year retention deadline
  lastError:       text("last_error"),                      // Last archival error message

  createdAt: timestamp("created_at").defaultNow().notNull(),
}, (t) => ({
  taxDocIdIdx:       uniqueIndex("idx_pw_tax_doc_id").on(t.taxDocId),
  paymentIdx:        index("idx_pw_tax_payment").on(t.relatedPaymentId),
  payoutIdx:         index("idx_pw_tax_payout").on(t.relatedPayoutId),
  customerIdx:       index("idx_pw_tax_customer").on(t.customerId),
  providerIdx:       index("idx_pw_tax_provider").on(t.providerId),
  documentTypeIdx:   index("idx_pw_tax_doc_type").on(t.documentType),
  statusIdx:         index("idx_pw_tax_status").on(t.status),
}));

export const insertPwTaxDocumentSchema = createInsertSchema(pwTaxDocuments).omit({
  id: true,
  createdAt: true,
});
export type InsertPwTaxDocument = z.infer<typeof insertPwTaxDocumentSchema>;
export type PwTaxDocument = typeof pwTaxDocuments.$inferSelect;

// ─────────────────────────────────────────────────────────────────────────────
// pw_reconciliation_reports — Daily reconciliation snapshots (Spec Section 15)
// ─────────────────────────────────────────────────────────────────────────────

export const pwReconciliationReports = pgTable("pw_reconciliation_reports", {
  id: serial("id").primaryKey(),

  reportId:   varchar("report_id").unique().notNull(),      // RECON-{date}-{nanoid6}
  reportDate: varchar("report_date").notNull(),             // YYYY-MM-DD — the day being reconciled
  generatedAt: timestamp("generated_at").defaultNow().notNull(),

  // ── Summary counters ────────────────────────────────────────────────────────
  totalPayments:       integer("total_payments").notNull().default(0),
  totalGrossCents:     integer("total_gross_cents").notNull().default(0),
  totalVatCents:       integer("total_vat_cents").notNull().default(0),
  totalProcessorFees:  integer("total_processor_fees").notNull().default(0),
  totalProviderPayouts: integer("total_provider_payouts").notNull().default(0),
  totalNetRevenue:     integer("total_net_revenue").notNull().default(0),

  totalTaxDocs:        integer("total_tax_docs").notNull().default(0),
  totalPayoutsCount:   integer("total_payouts_count").notNull().default(0),

  // ── Discrepancy flags ───────────────────────────────────────────────────────
  discrepancyCount:    integer("discrepancy_count").notNull().default(0),
  criticalIssues:      integer("critical_issues").notNull().default(0),

  // ── Full report payload ─────────────────────────────────────────────────────
  payload:   jsonb("payload").notNull().default({}),

  // ── Integrity chain ─────────────────────────────────────────────────────────
  integrityHash:    varchar("integrity_hash"),
  prevReportHash:   varchar("prev_report_hash"),

  status: varchar("status").notNull().default("complete"),  // complete | partial | failed
}, (t) => ({
  reportIdIdx:   uniqueIndex("idx_pw_recon_report_id").on(t.reportId),
  reportDateIdx: index("idx_pw_recon_date").on(t.reportDate),
}));

export type PwReconciliationReport = typeof pwReconciliationReports.$inferSelect;
